package com.giovannielena.restaurant.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="reservations") @Getter @Setter @NoArgsConstructor @AllArgsConstructor
public class Reservation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="reservation_id") private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(name="customer_name",nullable=false) private String customerName; @Column(name="customer_email") private String customerEmail; @Column(name="customer_phone") private String customerPhone; @Column(name="reservation_date",nullable=false) private LocalDate reservationDate; @Column(name="reservation_time",nullable=false) private LocalTime reservationTime; @Column(name="guest_count",nullable=false) private Integer guestCount; @Column(name="special_request") private String specialRequest; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.PENDING; @Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); public enum Status{PENDING,CONFIRMED,CANCELLED,COMPLETED} }